import{_ as t,b as a,e as r,a8 as d}from"./chunks/framework.CD0vREyi.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32","entity":"TCustomBackend","kind":"Class","declaration":"TCustomBackend = class(TThreadPersistent)","inheritance":["TObject","TPersistent","TPlainInterfacedPersistent","TNotifiablePersistent","TThreadPersistent","TCustomBackend"],"summary":"Abstract base class for bitmap surface backends in Graphics32, managing raw pixel memory allocations and platform-specific surface handles.","date":1787740222000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32/TCustomBackend/index.md","filePath":"api/GR32/TCustomBackend/index.md","lastUpdated":1787740222000,"timestamp":1787740222000,"datetime":"2026-08-26T10:30:22.000Z","contributors":[{"commits":1,"email":"anders@melander.dk","name":"Anders Melander","avatar":"https://gravatar.com/avatar/a6bff52a3ccbe999ab6406528ffe48f1","maintainer":false,"links":[]}]}'),o={name:"api/GR32/TCustomBackend/index.md"};function i(s,e,n,c,h,l){return a(),r("div",null,[...e[0]||(e[0]=[d('<h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p><code>TCustomBackend</code> is the abstract base class for all backend memory and surface managers in Graphics32.</p><p>It abstracts the allocation, lifetime, and OS handles for 32-bit pixel buffers from <code>TCustomBitmap32</code>. Concrete backend subclasses (such as <code>TMemoryBackend</code>, <code>TGDIBackend</code>, or <code>TLCLBackend</code>) inherit from <code>TCustomBackend</code> and implement platform-specific surface allocation routines by overriding <code>InitializeSurface</code> and <code>FinalizeSurface</code>.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to &quot;Constructors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><a href="./Constructors/Create">Create</a></td><td>Initializes a new <code>TCustomBackend</code> instance, optionally attaching it to an owner bitmap.</td></tr></tbody></table><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><a href="./Methods/Assign">Assign</a></td><td>Copies pixel buffer memory and dimensions from another backend instance.</td></tr><tr><td><a href="./Methods/ChangeSize">ChangeSize</a></td><td>Resizes the backing surface and reallocates pixel memory buffer.</td></tr><tr><td><a href="./Methods/Changing">Changing</a></td><td>Protected virtual method that triggers the <code>OnChanging</code> event before surface modifications.</td></tr><tr><td><a href="./Methods/Clear">Clear</a></td><td>Deallocates the surface and resets dimensions to zero.</td></tr><tr><td><a href="./Methods/Empty">Empty</a></td><td>Returns <code>True</code> if the backend surface buffer is unallocated or empty.</td></tr><tr><td><a href="./Methods/FinalizeSurface">FinalizeSurface</a></td><td>Protected virtual method that frees allocated OS surface handles and memory buffers.</td></tr><tr><td><a href="./Methods/InitializeSurface">InitializeSurface</a></td><td>Protected virtual method that allocates memory buffers and OS handles for specified dimensions.</td></tr></tbody></table><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Scope</th><th>Description</th></tr></thead><tbody><tr><td><a href="./Properties/Bits">Bits</a></td><td><code>PColor32Array</code></td><td>Public</td><td>Pointer to the contiguous 32-bit ARGB pixel buffer memory array.</td></tr></tbody></table><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><a href="./Events/OnChanging">OnChanging</a></td><td><code>TNotifyEvent</code></td><td>Fired immediately before backend surface dimensions or memory buffers change.</td></tr></tbody></table>',11)])])}const u=t(o,[["render",i]]);export{f as __pageData,u as default};
